import java.util.*;

public class PuzzleSolver {
    static int n;
    static int[][] grid;
    static boolean[][] used;
    static List<int[]> starts;
    static int[] targetSum;
    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {-1, 1, 0, 0};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            n = sc.nextInt();
            if (n == 0) break;
            grid = new int[n][n];
            used = new boolean[n][n];
            starts = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    grid[i][j] = sc.nextInt();
                    if (grid[i][j] < 0) {
                        starts.add(new int[]{i, j, Math.abs(grid[i][j])});
                        used[i][j] = true;
                    }
                }
            }
            targetSum = new int[starts.size()];
            for (int i = 0; i < starts.size(); i++) {
                targetSum[i] = starts.get(i)[2];
            }
            if (backtrack(0)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
        sc.close();
    }

    static boolean backtrack(int idx) {
        if (idx == starts.size()) {
            return true;
        }
        int x = starts.get(idx)[0];
        int y = starts.get(idx)[1];
        int target = targetSum[idx];

        for (int d = 0; d < 4; d++) {
            int sum = 0;
            int cx = x, cy = y;
            List<int[]> path = new ArrayList<>();
            while (true) {
                cx += dx[d];
                cy += dy[d];
                if (cx < 0 || cx >= n || cy < 0 || cy >= n) break;
                if (used[cx][cy]) break;
                sum += grid[cx][cy];
                path.add(new int[]{cx, cy});
                if (sum == target) {
                    // mark used
                    for (int[] p : path) used[p[0]][p[1]] = true;
                    if (backtrack(idx + 1)) return true;
                    // unmark
                    for (int[] p : path) used[p[0]][p[1]] = false;
                    break;
                }
                if (sum > target) break;
            }
        }
        return false;
    }
}

