    static int[] startX, startY, startVal;
    static int numStarts;
    static boolean[][] occupied;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            n = sc.nextInt();
            if (n == 0) break;
            grid = new int[n][n];
            List<int[]> starts = new ArrayList<>();
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) {
                    grid[i][j] = sc.nextInt();
                    if (grid[i][j] < 0) starts.add(new int[]{i, j, -grid[i][j]});
                }
            numStarts = starts.size();
            startX = new int[numStarts]; startY = new int[numStarts]; startVal = new int[numStarts];
            for (int i = 0; i < numStarts; i++) {
                startX[i] = starts.get(i)[0]; startY[i] = starts.get(i)[1]; startVal[i] = starts.get(i)[2];
            }
            occupied = new boolean[n][n];
            System.out.println(solve(0) ? "YES" : "NO");
        }
    }

    static int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};

    static boolean solve(int idx) {
        if (idx == numStarts) return true;
        int r = startX[idx], c = startY[idx], val = startVal[idx];
        // Try each direction
        for (int[] d : dirs) {
            List<int[]> cells = new ArrayList<>();
            int sum = 0;
            int cr = r + d[0], cc = c + d[1];
            boolean valid = true;
            while (cr >= 0 && cr < n && cc >= 0 && cc < n) {
                if (grid[cr][cc] < 0) { valid = false; break; } // passing through another start
                if (occupied[cr][cc]) { valid = false; break; } // occupied
                cells.add(new int[]{cr, cc});
                sum += grid[cr][cc];
                if (sum == val) break;
                if (sum > val) { valid = false; break; }
                cr += d[0]; cc += d[1];
            }
            if (!valid || sum != val || cells.isEmpty()) continue;
            // Mark cells
            for (int[] cell : cells) occupied[cell[0]][cell[1]] = true;
            if (solve(idx + 1)) return true;
            for (int[] cell : cells) occupied[cell[0]][cell[1]] = false;
        }
        return false;
    }
}

