public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int n;
    static int[][] a;
    static List<int[]> starts;
    static int[][] owner; // 0 = unused, otherwise index+1 of start occupying the cell

    static class Segment {
        int r1, c1, r2, c2; // inclusive
        List<int[]> cells = new ArrayList<>();
    }

    static List<Segment>[] options;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int nn;
            try {
                nn = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (nn == 0) break;

            n = nn;
            a = new int[n][n];
            starts = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    a[i][j] = fs.nextInt();
                    if (a[i][j] < 0) starts.add(new int[]{i, j, -a[i][j]});
                }
            }

            boolean ok = solve();
            out.append(ok ? "YES" : "NO").append('\n');
        }

        System.out.print(out.toString());
    }

    static boolean solve() {
        int m = starts.size();
        owner = new int[n][n];
        options = new ArrayList[m];
        for (int i = 0; i < m; i++) {
            options[i] = generateOptions(i);
            if (options[i].isEmpty()) return false;
        }

        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> options[i].size()));

        return dfs(0, order);
    }

    static List<Segment> generateOptions(int idx) {
        int sr = starts.get(idx)[0];
        int sc = starts.get(idx)[1];
        int target = starts.get(idx)[2];

        List<Segment> res = new ArrayList<>();

        // horizontal segments containing (sr, sc)
        for (int left = 0; left <= sc; left++) {
            int sum = 0;
            int startCount = 0;
            for (int right = left; right < n; right++) {
                if (right > sc && left > sc) break;
                if (left <= sc && sc <= right) {
                    sum += Math.abs(a[sr][right]);
                    if (a[sr][right] < 0) startCount++;
                    if (sum == target && startCount == 1) {
                        Segment seg = new Segment();
                        seg.r1 = seg.r2 = sr;
                        seg.c1 = left;
                        seg.c2 = right;
                        for (int c = left; c <= right; c++) seg.cells.add(new int[]{sr, c});
                        res.add(seg);
                    }
                    if (sum >= target) break;
                } else {
                    sum += Math.abs(a[sr][right]);
                    if (a[sr][right] < 0) startCount++;
                }
            }
        }

        // vertical segments containing (sr, sc)
        for (int top = 0; top <= sr; top++) {
            int sum = 0;
            int startCount = 0;
            for (int bottom = top; bottom < n; bottom++) {
                if (top <= sr && sr <= bottom) {
                    sum += Math.abs(a[bottom][sc]);
                    if (a[bottom][sc] < 0) startCount++;
                    if (sum == target && startCount == 1) {
                        Segment seg = new Segment();
                        seg.c1 = seg.c2 = sc;
                        seg.r1 = top;
                        seg.r2 = bottom;
                        for (int r = top; r <= bottom; r++) seg.cells.add(new int[]{r, sc});
                        res.add(seg);
                    }
                    if (sum >= target) break;
                } else {
                    sum += Math.abs(a[bottom][sc]);
                    if (a[bottom][sc] < 0) startCount++;
                }
            }
        }

        return res;
    }

    static boolean dfs(int pos, Integer[] order) {
        if (pos == order.length) {
            // Every non-start cell must be covered exactly once? The statement only asks solvability
            // by drawing a line from each start respecting rules. Cells not used are allowed.
            return true;
        }

        int idx = order[pos];

        for (Segment seg : options[idx]) {
            if (canPlace(idx, seg)) {
                place(idx, seg, idx + 1);
                if (dfs(pos + 1, order)) return true;
                place(idx, seg, 0);
            }
        }
        return false;
    }

    static boolean canPlace(int idx, Segment seg) {
        int sr = starts.get(idx)[0];
        int sc = starts.get(idx)[1];

        for (int[] cell : seg.cells) {
            int r = cell[0], c = cell[1];
            if (owner[r][c] != 0) return false;
            if (a[r][c] < 0 && !(r == sr && c == sc)) return false;
        }
        return true;
    }

    static void place(int idx, Segment seg, int val) {
        for (int[] cell : seg.cells) {
            owner[cell[0]][cell[1]] = val;
        }
    }
}

