int totalStarts;

bool isValid(int r, int c) {
    return r >= 0 && r < n && c >= 0 && c < n;
}

bool solve(int idx) {
    if (idx == totalStarts) {
        return true;
    }

    int r = starts[idx].first;
    int c = starts[idx].second;
    int target = targetSums[idx];

    // Try horizontal right
    for (int len = 1; len <= n - c; len++) {
        int sum = 0;
        bool valid = true;

        // Check cells to the right
        for (int j = 0; j < len && valid; j++) {
            int nc = c + j;
            if (!isValid(r, nc) || used[r][nc]) {
                valid = false;
                break;
            }
            if (grid[r][nc] < 0 && j > 0) {
                valid = false; // Can't pass through another starting point
                break;
            }
            sum += abs(grid[r][nc]);
        }

        if (valid && sum == target) {
            // Mark cells as used
            for (int j = 0; j < len; j++) {
                used[r][c + j] = true;
            }

            if (solve(idx + 1)) return true;

            // Backtrack
            for (int j = 0; j < len; j++) {
                used[r][c + j] = false;
            }
        }
    }

    // Try horizontal left
    for (int len = 1; len <= c + 1; len++) {
        int sum = 0;
        bool valid = true;

        for (int j = 0; j < len && valid; j++) {
            int nc = c - j;
            if (!isValid(r, nc) || used[r][nc]) {
                valid = false;
                break;
            }
            if (grid[r][nc] < 0 && j > 0) {
                valid = false;
                break;
            }
            sum += abs(grid[r][nc]);
        }

        if (valid && sum == target) {
            for (int j = 0; j < len; j++) {
                used[r][c - j] = true;
            }

            if (solve(idx + 1)) return true;

            for (int j = 0; j < len; j++) {
                used[r][c - j] = false;
            }
        }
    }

    // Try vertical down
    for (int len = 1; len <= n - r; len++) {
        int sum = 0;
        bool valid = true;

        for (int i = 0; i < len && valid; i++) {
            int nr = r + i;
            if (!isValid(nr, c) || used[nr][c]) {
                valid = false;
                break;
            }
            if (grid[nr][c] < 0 && i > 0) {
                valid = false;
                break;
            }
            sum += abs(grid[nr][c]);
        }

        if (valid && sum == target) {
            for (int i = 0; i < len; i++) {
                used[r + i][c] = true;
            }

            if (solve(idx + 1)) return true;

            for (int i = 0; i < len; i++) {
                used[r + i][c] = false;
            }
        }
    }

    // Try vertical up
    for (int len = 1; len <= r + 1; len++) {
        int sum = 0;
        bool valid = true;

        for (int i = 0; i < len && valid; i++) {
            int nr = r - i;
            if (!isValid(nr, c) || used[nr][c]) {
                valid = false;
                break;
            }
            if (grid[nr][c] < 0 && i > 0) {
                valid = false;
                break;
            }
            sum += abs(grid[nr][c]);
        }

        if (valid && sum == target) {
            for (int i = 0; i < len; i++) {
                used[r - i][c] = true;
            }

            if (solve(idx + 1)) return true;

            for (int i = 0; i < len; i++) {
                used[r - i][c] = false;
            }
        }
    }

    return false;
}

