#include <bits/stdc++.h>
using namespace std;

struct Source {
    int r, c, need;
};

int n;
vector<vector<int>> a;
vector<Source> srcs;
vector<vector<int>> used;

// Try to build one path for source idx from (r,c) with current sum rem.
// prevDir: 0=up,1=right,2=down,3=left, -1 means no previous direction yet.
bool dfs_cell(int idx, int r, int c, int rem, int prevDir);

const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, 1, 0, -1};

bool inside(int r, int c) {
    return r >= 0 && r < n && c >= 0 && c < n;
}

// After finishing one source, move to next source.
bool solve_source(int idx) {
    if (idx == (int)srcs.size()) return true;

    int r = srcs[idx].r;
    int c = srcs[idx].c;
    int need = srcs[idx].need;

    // Path starts at the source cell, which contributes nothing.
    // Must extend to at least one neighboring non-source cell.
    return dfs_cell(idx, r, c, need, -1);
}

bool dfs_cell(int idx, int r, int c, int rem, int prevDir) {
    // If rem == 0, current path is complete.
    if (rem == 0) {
        return solve_source(idx + 1);
    }

    // Continue straight if we already have a direction.
    if (prevDir != -1) {
        int nr = r + dr[prevDir], nc = c + dc[prevDir];
        if (!inside(nr, nc)) return false;
        if (used[nr][nc]) return false;
        if (a[nr][nc] < 0) return false; // cannot pass through another source

        int val = a[nr][nc];
        if (val > rem) return false;

        used[nr][nc] = 1;
        if (dfs_cell(idx, nr, nc, rem - val, prevDir)) return true;
        used[nr][nc] = 0;
        return false;
    }

    // Choose initial direction from the source.
    for (int d = 0; d < 4; ++d) {
        int nr = r + dr[d], nc = c + dc[d];
        if (!inside(nr, nc)) continue;
        if (used[nr][nc]) continue;
        if (a[nr][nc] < 0) continue; // cannot enter another source

        int val = a[nr][nc];
        if (val > rem) continue;

        used[nr][nc] = 1;
        if (dfs_cell(idx, nr, nc, rem - val, d)) return true;
        used[nr][nc] = 0;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (cin >> n) {
        if (n == 0) break;

        a.assign(n, vector<int>(n));
        srcs.clear();
        used.assign(n, vector<int>(n, 0));

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                cin >> a[i][j];
                if (a[i][j] < 0) {
                    srcs.push_back({i, j, -a[i][j]});
                    used[i][j] = 1; // source cells are occupied
                }
            }
        }

        // Small heuristic: solve larger requirements first.
        sort(srcs.begin(), srcs.end(), [](const Source& x, const Source& y) {
            return x.need > y.need;
        });

        cout << (solve_source(0) ? "YES" : "NO") << '\n';
    }

    return 0;
}

