        // But we start at starting point, so we don't add it yet? 
        // Let's interpret: The line includes the starting cell? Typically yes.
        // The sum of numbers on the line (including the starting point's absolute value) equals the starting number.
        // So we need to sum all cells along the line, including the start.
        // So we add target to sum immediately.
        sum += target; // because -grid[sx][sy] = target

        // Now move in direction dir
        int nx = sx + dx[dir];
        int ny = sy + dy[dir];

        while (is_valid(nx, ny) && !visited[nx][ny]) {
            int val = grid[nx][ny];
            if (val < 0) {
                // Another starting point: we cannot pass through it
                valid = false;
                break;
            }
            if (sum + val > target) {
                valid = false;
                break;
            }
            sum += val;
            visited[nx][ny] = true;
            path_x[path_len] = nx;
            path_y[path_len] = ny;
            path_len++;
            if (sum == target) {
                // We've reached target exactly
                break;
            }
            nx += dx[dir];
            ny += dy[dir];
        }

        if (valid && sum == target) {
            // Success for this starting point
            if (backtrack(idx + 1, starts, start_vals, num_starts)) {
                return true;
            }
        }

        // Backtrack: unmark visited cells
        for (int i = 0; i < path_len; i++) {
            visited[path_x[i]][path_y[i]] = false;
        }
    }

    return false;
}

