void precompute_moves(int si) {
    int r = starts[si][0], c = starts[si][1];
    int target = -grid[r][c];
    nmoves[si] = 0;
    for (int d = 0; d < 4; d++) {
        int sum = 0;
        for (int l = 1; l < n; l++) {
            int nr = r + dx[d]*l, nc = c + dy[d]*l;
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) break;
            if (grid[nr][nc] < 0) break; // another start point
            sum += grid[nr][nc];
            if (sum == target) {
                moves[si][nmoves[si]].dir = d;
                moves[si][nmoves[si]].len = l;
                nmoves[si]++;
                break; // sum can only equal target once if all positive
            }
            if (sum > target) break;
        }
    }
}

int solve(int si) {
    if (si == nstarts) return 1;
    int r = starts[si][0], c = starts[si][1];
    for (int m = 0; m < nmoves[si]; m++) {
        int d = moves[si][m].dir, l = moves[si][m].len;
        // Check if cells are free
        int ok = 1;
        for (int k = 1; k <= l; k++) {
            int nr = r + dx[d]*k, nc = c + dy[d]*k;
            if (used[nr][nc]) { ok = 0; break; }
        }
        if (!ok) continue;
        // Mark cells
        for (int k = 1; k <= l; k++) {
            int nr = r + dx[d]*k, nc = c + dy[d]*k;
            used[nr][nc] = si+1;
        }
        if (solve(si+1)) return 1;
        // Unmark
        for (int k = 1; k <= l; k++) {
            int nr = r + dx[d]*k, nc = c + dy[d]*k;
            used[nr][nc] = 0;
        }
    }
    return 0;
}

