#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 8
#define MAXS 20
#define MAXMASK (1<<16)

typedef struct {
    int cells[16];
    int len;
    int mask;
} Option;

static int n;
static int a[MAXN][MAXN];

static int starts_r[MAXS], starts_c[MAXS], starts_need[MAXS];
static int scnt;

static Option opts[MAXS][256];
static int optCnt[MAXS];

static int suffixUnion[MAXS + 1];
static int orderIdx[MAXS];

static int popcount_int(int x) {
    int c = 0;
    while (x) {
        x &= x - 1;
        c++;
    }
    return c;
}

static void add_option(int sid, int *cells, int len) {
    int mask = 0;
    for (int i = 0; i < len; i++) mask |= (1 << cells[i]);
    opts[sid][optCnt[sid]].len = len;
    opts[sid][optCnt[sid]].mask = mask;
    for (int i = 0; i < len; i++) opts[sid][optCnt[sid]].cells[i] = cells[i];
    optCnt[sid]++;
}

static void gen_options_for_start(int sid) {
    int sr = starts_r[sid], sc = starts_c[sid], need = starts_need[sid];
    int tmp[16];

    // Up
    {
        int sum = 0, len = 0, startSeen = 0;
        for (int r = sr - 1; r >= 0; r--) {
            if (a[r][sc] < 0) startSeen++;
            if (startSeen >= 1) break; // cannot pass through another starting point
            sum += a[r][sc];
            tmp[len++] = r * n + sc;
            if (sum == need) add_option(sid, tmp, len);
        }
    }
    // Down
    {
        int sum = 0, len = 0, startSeen = 0;
        for (int r = sr + 1; r < n; r++) {
            if (a[r][sc] < 0) startSeen++;
            if (startSeen >= 1) break;
            sum += a[r][sc];
            tmp[len++] = r * n + sc;
            if (sum == need) add_option(sid, tmp, len);
        }
    }
    // Left
    {
        int sum = 0, len = 0, startSeen = 0;
        for (int c = sc - 1; c >= 0; c--) {
            if (a[sr][c] < 0) startSeen++;
            if (startSeen >= 1) break;
            sum += a[sr][c];
            tmp[len++] = sr * n + c;
            if (sum == need) add_option(sid, tmp, len);
        }
    }
    // Right
    {
        int sum = 0, len = 0, startSeen = 0;
        for (int c = sc + 1; c < n; c++) {
            if (a[sr][c] < 0) startSeen++;
            if (startSeen >= 1) break;
            sum += a[sr][c];
            tmp[len++] = sr * n + c;
            if (sum == need) add_option(sid, tmp, len);
        }
    }
}

static int dfs(int idx, int usedMask) {
    if (idx == scnt) return 1;

    // pruning: if some future start has no possible non-conflicting option
    int sid = orderIdx[idx];
    for (int i = 0; i < optCnt[sid]; i++) {
        if ((opts[sid][i].mask & usedMask) == 0) {
            int newMask = usedMask | opts[sid][i].mask;
            if (dfs(idx + 1, newMask)) return 1;
        }
    }
    return 0;
}

static int cmp_order(const void *p1, const void *p2) {
    int i = *(const int*)p1;
    int j = *(const int*)p2;
    if (optCnt[i] != optCnt[j]) return optCnt[i] - optCnt[j];
    return starts_need[i] - starts_need[j];
}

int main(void) {
    while (scanf("%d", &n) == 1 && n) {
        scnt = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                scanf("%d", &a[i][j]);
                if (a[i][j] < 0) {
                    starts_r[scnt] = i;
                    starts_c[scnt] = j;
                    starts_need[scnt] = -a[i][j];
                    scnt++;
                }
            }
        }

        int ok = 1;
        for (int i = 0; i < scnt; i++) {
            optCnt[i] = 0;
            gen_options_for_start(i);
            if (optCnt[i] == 0) ok = 0;
        }

        if (!ok) {
            printf("NO\n");
            continue;
        }

        for (int i = 0; i < scnt; i++) orderIdx[i] = i;
        qsort(orderIdx, scnt, sizeof(int), cmp_order);

        ok = dfs(0, 0);
        printf(ok ? "YES\n" : "NO\n");
    }
    return 0;
}

