def solve_case(n, grid):
    starts = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] < 0:
                starts.append((i, j, -grid[i][j]))  # target sum

    m = len(starts)
    if m == 0:
        return True

    # Precompute all possible straight segments for each start.
    # A segment is a set of cells starting at the start cell and extending
    # in one of 4 directions, stopping before another start if encountered.
    # Sum of values on the segment must equal target.
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start_set = {(r, c) for r, c, _ in starts}
    options = []

    for idx, (r, c, target) in enumerate(starts):
        segs = []
        for dr, dc in dirs:
            s = 0
            cells = []
            nr, nc = r, c
            encountered_other_start = False
            while 0 <= nr < n and 0 <= nc < n:
                if (nr, nc) != (r, c) and (nr, nc) in start_set:
                    encountered_other_start = True
                    break
                s += abs(grid[nr][nc])
                cells.append((nr, nc))
                if s == target:
                    segs.append(cells[:])
                    # continue not allowed because all numbers are positive in magnitude,
                    # so sum would only increase further
                    break
                if s > target:
                    break
                nr += dr
                nc += dc
        if not segs:
            return False
        options.append(segs)

    # Order starts by fewest options first for backtracking
    order = sorted(range(m), key=lambda i: len(options[i]))
    used = [[False] * n for _ in range(n)]

    def dfs(pos):
        if pos == m:
            return True
        si = order[pos]
        for seg in options[si]:
            ok = True
            for r, c in seg:
                if used[r][c]:
                    ok = False
                    break
            if not ok:
                continue
            for r, c in seg:
                used[r][c] = True
            if dfs(pos + 1):
                return True
            for r, c in seg:
                used[r][c] = False
        return False

    return dfs(0)

